/**
 * DTCG JSON → TypeScript types + Zod schemas 변환기
 */

import { flattenTokens, type DtcgFile } from '../schema/dtcg.schema.js'
import type { TokenBridgeConfig } from '../config.js'

const GENERATED_HEADER = `/**
 * generated by figma-token-bridge — DO NOT EDIT DIRECTLY
 * Re-run 'figma-token-bridge generate' to update.
 */\n\n`

const ZOD_IMPORT = `import { z } from 'zod'\n\n`

/** SCREAMING_SNAKE_CASE 변환: 'PrimitiveSpacing' → 'PRIMITIVE_SPACING' */
function toScreamingSnake(s: string): string {
  return s.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase()
}

function toConstValuesArray(name: string, values: string[]): string {
  const items = values.map(v => `  '${v}'`).join(',\n')
  return `export const ${toScreamingSnake(name)}_VALUES = [\n${items},\n] as const\n`
}

function toZodEnum(name: string, values: string[]): string {
  const items = values.map(v => `  '${v}'`).join(',\n')
  return `export const ${name} = z.enum([\n${items},\n])\nexport type ${name.replace('Schema', '')} = z.infer<typeof ${name}>\n`
}

function toTypeUnion(name: string, values: string[]): string {
  const union = values.map(v => `'${v}'`).join(' | ')
  return `export type ${name} = ${union}\n`
}

function toPascalCase(s: string): string {
  return s
    .split(/[-_]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join('')
}

/**
 * camelCase / snake_case → kebab-case.
 * Style Dictionary의 `name/kebab` transform과 동일 정책으로 정렬해
 * CSS(`tokens.semantic.css`)와 TS(`tokens.ts`) 산출물의 토큰 표기를 일치시킨다.
 * 예: 'lnbDefault' → 'lnb-default', 'brandSubtle' → 'brand-subtle'.
 */
function toKebab(s: string): string {
  return s
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/_/g, '-')
    .toLowerCase()
}

export function generateTypeScript(
  primitiveFile: DtcgFile | undefined,
  semanticFile: DtcgFile | undefined,
  customFile: DtcgFile | undefined,
  config: TokenBridgeConfig,
): string {
  const useZod = config.typescript?.zod ?? false
  const namespace = config.namespace
  const lines = [GENERATED_HEADER]
  if (useZod) lines.push(ZOD_IMPORT)

  const processTier = (file: DtcgFile, prefix: string) => {
    const tokens = flattenTokens(file)
    const categories = [...new Set(tokens.map(([p]) => p.split('.')[0]))]

    for (const category of categories) {
      const categoryTokens = tokens.filter(([p]) => p.startsWith(`${category}.`))
      let paths: string[]

      if (category === 'color' && prefix === 'Primitive') {
        paths = categoryTokens.map(
          ([p]) => `${namespace}-${toKebab(p.slice(category.length + 1).replace(/\./g, '-'))}`,
        )
      } else {
        paths = categoryTokens.map(([p]) =>
          toKebab(p.slice(category.length + 1).replace(/\./g, '-')),
        )
      }

      const typeName = `${prefix}${toPascalCase(category)}`
      lines.push(`/** ${prefix} ${category} token names */`)
      lines.push(useZod ? toZodEnum(`${typeName}Schema`, paths) : toTypeUnion(typeName, paths))

      if (category === 'color' && prefix === 'Semantic') {
        lines.push(`\nexport function semanticColor(token: SemanticColor): string {
  return \`var(--${namespace}-color-\${token.replace(/\\./g, '-')})\`
}\n`)
      }
    }
  }

  if (primitiveFile) processTier(primitiveFile, 'Primitive')
  if (semanticFile) processTier(semanticFile, 'Semantic')
  if (customFile) processTier(customFile, 'Custom')

  return lines.join('\n')
}

/**
 * 토큰 zod 스키마를 emit.
 * 단일 파일에 VALUES const tuple + zod schema + type alias 모두 포함.
 *
 * @param valuesImportPath 있으면 values를 해당 경로에서 import (별도 valuesOutput 파일 사용),
 *                         없으면 같은 파일에 VALUES를 export한다 (self-contained).
 */
export function generateTokenSchemas(
  primitiveFile: DtcgFile | undefined,
  semanticFile: DtcgFile | undefined,
  customFile: DtcgFile | undefined,
  config: TokenBridgeConfig,
  valuesImportPath?: string,
): string {
  const namespace = config.namespace
  const lines = [GENERATED_HEADER, ZOD_IMPORT.trimEnd()]

  const valuesNames: string[] = []
  const valuesLines: string[] = []
  const schemaLines: string[] = []

  const processTier = (file: DtcgFile, prefix: string) => {
    const tokens = flattenTokens(file)
    const categories = [...new Set(tokens.map(([p]) => p.split('.')[0]))]

    for (const category of categories) {
      const categoryTokens = tokens.filter(([p]) => p.startsWith(`${category}.`))
      let paths: string[]
      if (category === 'color' && prefix === 'Primitive') {
        paths = categoryTokens.map(
          ([p]) => `${namespace}-${toKebab(p.slice(category.length + 1).replace(/\./g, '-'))}`,
        )
      } else {
        paths = categoryTokens.map(([p]) =>
          toKebab(p.slice(category.length + 1).replace(/\./g, '-')),
        )
      }

      const typeName = `${prefix}${toPascalCase(category)}`
      const valuesName = `${toScreamingSnake(typeName)}_VALUES`
      valuesNames.push(valuesName)

      if (!valuesImportPath) {
        valuesLines.push(`/** ${prefix} ${category} token names (runtime values) */`)
        valuesLines.push(toConstValuesArray(typeName, paths).trimEnd())
        valuesLines.push('')
      }

      schemaLines.push(`/** ${prefix} ${category} token schema */`)
      schemaLines.push(`export const ${typeName}Schema = z.enum(${valuesName})`)
      schemaLines.push(`export type ${typeName} = z.infer<typeof ${typeName}Schema>`)
      schemaLines.push('')
    }
  }

  if (primitiveFile) processTier(primitiveFile, 'Primitive')
  if (semanticFile) processTier(semanticFile, 'Semantic')
  if (customFile) processTier(customFile, 'Custom')

  if (valuesImportPath) {
    lines.push(`import {\n  ${valuesNames.join(',\n  ')},\n} from '${valuesImportPath}'`)
    lines.push('')
  } else {
    lines.push(valuesLines.join('\n'))
  }
  lines.push(schemaLines.join('\n'))

  return lines.join('\n')
}

/**
 * 토큰 값을 런타임 const tuple 배열로 emit.
 * type-only 출력(`tokens.ts`)과 동일한 값 목록을, zod/추출기 등에서 사용할 수 있도록 런타임 값으로 export.
 */
export function generateTokenValues(
  primitiveFile: DtcgFile | undefined,
  semanticFile: DtcgFile | undefined,
  customFile: DtcgFile | undefined,
  config: TokenBridgeConfig,
): string {
  const namespace = config.namespace
  const lines = [GENERATED_HEADER]

  const processTier = (file: DtcgFile, prefix: string) => {
    const tokens = flattenTokens(file)
    const categories = [...new Set(tokens.map(([p]) => p.split('.')[0]))]

    for (const category of categories) {
      const categoryTokens = tokens.filter(([p]) => p.startsWith(`${category}.`))
      let paths: string[]

      if (category === 'color' && prefix === 'Primitive') {
        paths = categoryTokens.map(
          ([p]) => `${namespace}-${toKebab(p.slice(category.length + 1).replace(/\./g, '-'))}`,
        )
      } else {
        paths = categoryTokens.map(([p]) =>
          toKebab(p.slice(category.length + 1).replace(/\./g, '-')),
        )
      }

      const typeName = `${prefix}${toPascalCase(category)}`
      lines.push(`/** ${prefix} ${category} token names */`)
      lines.push(toConstValuesArray(typeName, paths))
    }
  }

  if (primitiveFile) processTier(primitiveFile, 'Primitive')
  if (semanticFile) processTier(semanticFile, 'Semantic')
  if (customFile) processTier(customFile, 'Custom')

  return lines.join('\n')
}
